#include <bits/stdc++.h>
using namespace std;

int n;
vector<int> color_;
vector<vector<int>> adj;
vector<long long> answer;

struct Data {
    unordered_map<int,long long> cnt;
    long long maxFreq = 0;
    long long sumAtMax = 0;
};

vector<Data*> nodeData;

void addColor(Data* d, int c, long long delta) {
    d->cnt[c] += delta;
    long long v = d->cnt[c];
    if (v > d->maxFreq) {
        d->maxFreq = v;
        d->sumAtMax = c;
    } else if (v == d->maxFreq) {
        d->sumAtMax += c;
    }
}

void dfs(int u, int parent) {
    Data* du = new Data();
    addColor(du, color_[u], 1);
    nodeData[u] = du;
    for (int v : adj[u]) {
        if (v == parent) continue;
        dfs(v, u);
        Data*& pu = nodeData[u];
        Data*& pv = nodeData[v];
        if (pv->cnt.size() > pu->cnt.size()) swap(pu, pv);
        // merge smaller (pv) into larger (pu)
        for (auto& [c, cnt] : pv->cnt) {
            addColor(pu, c, cnt);
        }
        delete pv;
        pv = nullptr;
    }
    answer[u] = nodeData[u]->sumAtMax;
}

int main(){
    cin >> n;
    color_.assign(n+1, 0);
    for (int i = 1; i <= n; i++) cin >> color_[i];
    adj.assign(n+1, {});
    for (int i = 0; i < n-1; i++) {
        int a, b; cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    answer.assign(n+1, 0);
    nodeData.assign(n+1, nullptr);
    dfs(1, 0);
    for (int i = 1; i <= n; i++) {
        cout << answer[i] << (i<n ? ' ' : '\n');
    }
}

#include <bits/stdc++.h>
using namespace std;

int n;
vector<vector<int>> adj;
vector<int> depth_;
vector<int> answer;

struct Data {
    unordered_map<int,long long> cnt;  // key = ABSOLUTE depth from root
    long long bestCount = 0;
    int bestDepth = -1;                // absolute depth achieving bestCount, smallest wins ties
};

vector<Data*> nodeData;

void addAt(Data* d, int absDepth, long long delta) {
    d->cnt[absDepth] += delta;
    long long v = d->cnt[absDepth];
    if (v > d->bestCount || (v == d->bestCount && absDepth < d->bestDepth)) {
        d->bestCount = v;
        d->bestDepth = absDepth;
    }
}

void dfs(int u, int parent) {
    Data* du = new Data();
    addAt(du, depth_[u], 1);
    nodeData[u] = du;
    for (int v : adj[u]) {
        if (v == parent) continue;
        depth_[v] = depth_[u] + 1;
        dfs(v, u);
        Data*& pu = nodeData[u];
        Data*& pv = nodeData[v];
        // Because both maps are keyed by the SAME absolute-depth coordinate
        // system, merging never requires re-indexing/shifting -- we can
        // simply keep whichever map is larger and fold the smaller one in.
        if (pv->cnt.size() > pu->cnt.size()) swap(pu, pv);
        for (auto& [d, c] : pv->cnt) {
            addAt(pu, d, c);
        }
        delete pv;
        pv = nullptr;
    }
    // relative depth = absolute depth of the best level minus u's own absolute depth
    answer[u] = nodeData[u]->bestDepth - depth_[u];
}

int main(){
    cin >> n;
    adj.assign(n+1, {});
    for (int i = 0; i < n-1; i++) {
        int a, b; cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    depth_.assign(n+1, 0);
    answer.assign(n+1, 0);
    nodeData.assign(n+1, nullptr);
    depth_[1] = 0;
    dfs(1, 0);
    for (int i = 1; i <= n; i++) {
        cout << answer[i] << (i<n ? ' ' : '\n');
    }
}

#include <bits/stdc++.h>
using namespace std;

int n;
vector<vector<pair<int,int>>> adj; // (to, weight)
int LOG;
vector<vector<int>> up_;
vector<int> depth_, tin_, tout_;
vector<long long> distW;
int timer_ = 0;

void dfs(int u, int p, int w) {
    tin_[u] = timer_++;
    up_[0][u] = p;
    depth_[u] = (p == -1) ? 0 : depth_[p] + 1;
    distW[u] = (p == -1) ? 0 : distW[p] + w;
    for (int k = 1; k < LOG; k++)
        up_[k][u] = (up_[k-1][u] == -1) ? -1 : up_[k-1][up_[k-1][u]];
    for (auto &e : adj[u]) {
        int v = e.first, wt = e.second;
        if (v != p) dfs(v, u, wt);
    }
    tout_[u] = timer_++;
}

bool isAncestor(int u, int v) {
    return tin_[u] <= tin_[v] && tout_[v] <= tout_[u];
}

int lca(int u, int v) {
    if (isAncestor(u, v)) return u;
    if (isAncestor(v, u)) return v;
    for (int k = LOG - 1; k >= 0; k--) {
        if (up_[k][u] != -1 && !isAncestor(up_[k][u], v)) u = up_[k][u];
    }
    return up_[0][u];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    adj.assign(n + 1, {});
    for (int i = 0; i < n - 1; i++) {
        int a, b, w;
        cin >> a >> b >> w;
        adj[a].push_back({b, w});
        adj[b].push_back({a, w});
    }
    LOG = 1;
    while ((1 << LOG) < n + 1) LOG++;
    LOG++;
    up_.assign(LOG, vector<int>(n + 1, -1));
    depth_.assign(n + 1, 0);
    tin_.assign(n + 1, 0);
    tout_.assign(n + 1, 0);
    distW.assign(n + 1, 0);
    dfs(1, -1, 0);

    int q;
    cin >> q;
    while (q--) {
        int k;
        cin >> k;
        vector<int> S(k);
        for (auto &x : S) cin >> x;

        sort(S.begin(), S.end(), [](int a, int b) { return tin_[a] < tin_[b]; });

        vector<int> nodes = S;
        for (int i = 1; i < k; i++) nodes.push_back(lca(S[i-1], S[i]));
        sort(nodes.begin(), nodes.end(), [](int a, int b) { return tin_[a] < tin_[b]; });
        nodes.erase(unique(nodes.begin(), nodes.end()), nodes.end());

        long long total = 0;
        vector<int> stk;
        stk.push_back(nodes[0]);
        for (int i = 1; i < (int)nodes.size(); i++) {
            int v = nodes[i];
            int l = lca(stk.back(), v);
            while (stk.size() > 1 && depth_[stk[stk.size()-2]] >= depth_[l]) {
                total += distW[stk.back()] - distW[stk[stk.size()-2]];
                stk.pop_back();
            }
            if (stk.back() != l) {
                total += distW[stk.back()] - distW[l];
                stk.pop_back();
                stk.push_back(l);
            }
            stk.push_back(v);
        }
        while (stk.size() > 1) {
            total += distW[stk.back()] - distW[stk[stk.size()-2]];
            stk.pop_back();
        }
        cout << total << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n;
vector<vector<int>> adj;
int LOG;
vector<vector<int>> up_;
vector<int> depth_, tin_, tout_;
int timer_ = 0;

void dfs(int u, int p) {
    tin_[u] = timer_++;
    up_[0][u] = p;
    depth_[u] = (p == -1) ? 0 : depth_[p] + 1;
    for (int k = 1; k < LOG; k++)
        up_[k][u] = (up_[k-1][u] == -1) ? -1 : up_[k-1][up_[k-1][u]];
    for (int v : adj[u]) if (v != p) dfs(v, u);
    tout_[u] = timer_++;
}

bool isAncestor(int u, int v) {
    return tin_[u] <= tin_[v] && tout_[v] <= tout_[u];
}

int lca(int u, int v) {
    if (isAncestor(u, v)) return u;
    if (isAncestor(v, u)) return v;
    for (int k = LOG - 1; k >= 0; k--) {
        if (up_[k][u] != -1 && !isAncestor(up_[k][u], v)) u = up_[k][u];
    }
    return up_[0][u];
}

vector<vector<int>> vAdj;   // virtual tree children lists (reset per query)
vector<char> isCapital;
long long ansCount;
bool impossible;

// Returns true if an unguarded capital's path still reaches u without a placed guard.
bool solve(int u) {
    int hard = 0, soft = 0; // active children merging via edge length 1 ("hard", no room to cut) vs >1 ("soft", cuttable)
    for (int c : vAdj[u]) {
        bool activeChild = solve(c);
        if (activeChild) {
            int elen = depth_[c] - depth_[u];
            if (elen == 1) hard++; else soft++;
        }
    }
    if (isCapital[u]) {
        if (hard > 0) { impossible = true; }
        ansCount += soft; // every soft (cuttable) incoming branch must be cut; u itself is a capital, can't absorb anything
        return true;
    } else {
        if (hard >= 2) {
            // two or more capital branches meet at u via direct real-tree edges: only way to
            // separate them is to remove u itself.
            ansCount += 1;
            return false;
        }
        int costB = max(0, soft - (1 - hard)); // cut down soft branches, keep at most (1-hard) of them free
        int costA = 1; // remove u itself, absorbing everything
        if (costA <= costB) {
            ansCount += costA;
            return false;
        } else {
            ansCount += costB;
            return (hard + soft) > 0;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    adj.assign(n + 1, {});
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    LOG = 1;
    while ((1 << LOG) < n + 1) LOG++;
    LOG++;
    up_.assign(LOG, vector<int>(n + 1, -1));
    depth_.assign(n + 1, 0);
    tin_.assign(n + 1, 0);
    tout_.assign(n + 1, 0);
    dfs(1, -1);

    vAdj.assign(n + 1, {});
    isCapital.assign(n + 1, 0);

    int q;
    cin >> q;
    while (q--) {
        int k;
        cin >> k;
        vector<int> S(k);
        for (auto &x : S) cin >> x;

        vector<int> touched; // every vertex that becomes part of the virtual tree this query

        sort(S.begin(), S.end(), [](int a, int b) { return tin_[a] < tin_[b]; });
        for (int v : S) isCapital[v] = 1;

        vector<int> nodes = S;
        for (int i = 1; i < k; i++) nodes.push_back(lca(S[i-1], S[i]));
        sort(nodes.begin(), nodes.end(), [](int a, int b) { return tin_[a] < tin_[b]; });
        nodes.erase(unique(nodes.begin(), nodes.end()), nodes.end());
        touched = nodes;

        int root;
        if (nodes.size() == 1) {
            root = nodes[0];
        } else {
            vector<int> stk;
            stk.push_back(nodes[0]);
            for (int i = 1; i < (int)nodes.size(); i++) {
                int v = nodes[i];
                int l = lca(stk.back(), v);
                while (stk.size() > 1 && depth_[stk[stk.size()-2]] >= depth_[l]) {
                    vAdj[stk[stk.size()-2]].push_back(stk.back());
                    stk.pop_back();
                }
                if (stk.back() != l) {
                    vAdj[l].push_back(stk.back());
                    stk.pop_back();
                    stk.push_back(l);
                }
                stk.push_back(v);
            }
            while (stk.size() > 1) {
                vAdj[stk[stk.size()-2]].push_back(stk.back());
                stk.pop_back();
            }
            root = stk[0];
        }

        ansCount = 0;
        impossible = false;
        solve(root);

        cout << (impossible ? -1 : ansCount) << "\n";

        // reset state for next query
        for (int v : touched) { vAdj[v].clear(); }
        for (int v : S) isCapital[v] = 0;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Shared canonical-label map for the current pair of trees being compared.
// Mapping a SORTED vector of children canonical-ids -> a compact new id.
map<vector<long long>, long long> labelId;
long long nextId = 1;

long long computeLabel(int u, vector<vector<int>>& children) {
    vector<long long> childLabels;
    childLabels.reserve(children[u].size());
    for (int c : children[u]) childLabels.push_back(computeLabel(c, children));
    sort(childLabels.begin(), childLabels.end()); // order of children is irrelevant to isomorphism
    auto it = labelId.find(childLabels);
    if (it != labelId.end()) return it->second;
    long long id = nextId++;
    labelId[childLabels] = id;
    return id;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n1;
        cin >> n1;
        vector<vector<int>> children1(n1 + 1);
        for (int i = 2; i <= n1; i++) {
            int p; cin >> p;
            children1[p].push_back(i);
        }
        int n2;
        cin >> n2;
        vector<vector<int>> children2(n2 + 1);
        for (int i = 2; i <= n2; i++) {
            int p; cin >> p;
            children2[p].push_back(i);
        }
        if (n1 != n2) {
            cout << "NO\n";
            continue;
        }
        labelId.clear();
        nextId = 1;
        long long l1 = computeLabel(1, children1);
        long long l2 = computeLabel(1, children2);
        cout << (l1 == l2 ? "YES" : "NO") << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Shared canonical-label map for the current pair of trees being compared.
map<vector<long long>, long long> labelId;
long long nextId = 1;

long long dfsLabel(int u, int parent, vector<vector<int>>& adj) {
    vector<long long> childLabels;
    for (int v : adj[u]) {
        if (v == parent) continue;
        childLabels.push_back(dfsLabel(v, u, adj));
    }
    sort(childLabels.begin(), childLabels.end());
    auto it = labelId.find(childLabels);
    if (it != labelId.end()) return it->second;
    long long id = nextId++;
    labelId[childLabels] = id;
    return id;
}

// Find the 1 or 2 centroids of the tree rooted arbitrarily at vertex 1.
vector<int> findCentroids(int n, vector<vector<int>>& adj) {
    vector<int> sz(n + 1, 0), par(n + 1, 0);
    function<void(int,int)> dfsSize = [&](int u, int p) {
        par[u] = p;
        sz[u] = 1;
        for (int v : adj[u]) if (v != p) { dfsSize(v, u); sz[u] += sz[v]; }
    };
    dfsSize(1, 0);
    vector<int> centroids;
    for (int u = 1; u <= n; u++) {
        int mx = n - sz[u]; // component through the "parent" direction
        for (int v : adj[u]) if (v != par[u]) mx = max(mx, sz[v]);
        if (mx <= n / 2) centroids.push_back(u);
    }
    return centroids;
}

// Canonical form of an unrooted tree: root at the centroid.
// If there are two centroids (always adjacent), combine the two
// centroid-rooted subtree labels (each blocking the edge toward the other)
// as if there were a virtual root between them.
long long canonicalForm(int n, vector<vector<int>>& adj) {
    vector<int> centroids = findCentroids(n, adj);
    if (centroids.size() == 1) {
        return dfsLabel(centroids[0], 0, adj);
    } else {
        int c1 = centroids[0], c2 = centroids[1];
        long long l1 = dfsLabel(c1, c2, adj); // c1's subtree, blocking edge to c2
        long long l2 = dfsLabel(c2, c1, adj); // c2's subtree, blocking edge to c1
        vector<long long> combo = {min(l1, l2), max(l1, l2)};
        auto it = labelId.find(combo);
        if (it != labelId.end()) return it->second;
        long long id = nextId++;
        labelId[combo] = id;
        return id;
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n1;
        cin >> n1;
        vector<vector<int>> adj1(n1 + 1);
        for (int i = 0; i < n1 - 1; i++) {
            int a, b; cin >> a >> b;
            adj1[a].push_back(b);
            adj1[b].push_back(a);
        }
        int n2;
        cin >> n2;
        vector<vector<int>> adj2(n2 + 1);
        for (int i = 0; i < n2 - 1; i++) {
            int a, b; cin >> a >> b;
            adj2[a].push_back(b);
            adj2[b].push_back(a);
        }
        if (n1 != n2) {
            cout << "NO\n";
            continue;
        }
        labelId.clear();
        nextId = 1;
        long long l1 = canonicalForm(n1, adj1);
        long long l2 = canonicalForm(n2, adj2);
        cout << (l1 == l2 ? "YES" : "NO") << "\n";
    }
    return 0;
}
